/*!40000 ALTER TABLE `reviews` DISABLE KEYS */;
INSERT INTO `reviews` VALUES (178301,23,298001,46,1007,2,'稍微有点太辣了，受不了。窗口打饭快慢太慢，排队时长太长要十多分钟，价格也有点虚高，感觉不够干净新鲜。','2026/1/10 7:03'),(178302,14,298002,49,1007,2,'只有辣味没有香味，价格不值。窗口打饭效率低，排队时长太久超过10分钟，食材看起来不怎么干净新鲜。','2026/1/10 7:03'),(178303,22,298003,71,1009,5,'两种口味一次满足，价格划算。窗口打饭快，排队时长短，食材确保干净新鲜，特别喜欢。','2026/1/10 7:24'),(178304,14,298004,71,1009,2,'分量太少了，价格贵。窗口打饭慢，排队时长超过10分钟，肉质感觉不够干净新鲜，差评。','2026/1/10 7:26'),(178305,10,298005,71,1009,4,'口味平衡得不错，价格合适。排队时长正常，窗口打饭节奏挺好，肉类看起来都干净新鲜。','2026/1/10 7:26'),(178306,17,298006,3,1001,2,'满盘全是土豆，牛肉要靠“寻宝”才能找到，感觉像在吃土豆盖饭......','2026/1/10 7:30'),(178307,28,298007,49,1007,4,'口味还行，价格公道。窗口打饭速度比较稳定，排队时长适中，配料看起来都是干净新鲜的，还行。','2026/1/10 7:31'),(178308,16,298008,71,1009,5,'烧鸭的油润搭配白切鸡的清爽，简直是神仙组合。米饭也蒸得粒粒分明，是非常精致的食堂餐。','2026/1/10 7:31'),(178309,5,298009,62,1008,4,'酱香浓，微辣开胃，炒得干爽。价格不贵，排队时间短。','2026/1/10 8:06'),(178310,9,298010,20,1004,4,'豆沙馅细腻甜度适中，面皮松软喧腾，窗口干净，拿取快，很喜欢','2026/1/10 8:14'),(178311,6,298011,43,1007,4,'面的劲道十足，鸡杂酸辣入味特别开胃，是我最近在食堂吃过最满意的面条了，强烈推荐给大家。','2026/1/10 8:14'),(178312,1,298012,1,1001,5,'15元一大盘，黑椒味很正，牛肉片大且不塞牙，师傅炒菜手速极快。','2026/1/10 8:29'),(178313,15,298013,46,1007,4,'口味中规中矩，17元的价格能接受。窗口打饭快慢还可以，排队时长不算太久，食材整体看着还算干净新鲜。','2026/1/10 8:35'),(178314,7,298014,63,1008,5,'味道还行，不踩雷。价格正常，现炒出餐，卫生不错。','2026/1/10 8:47'),(178315,11,298015,71,1009,1,'烧鸭给的都是边角料，白切鸡没几块肉。整体性价比极低，感觉被坑了，以后不会再买。','2026/1/10 8:58'),(178316,24,298016,49,1007,5,'麻辣程度刚刚好，花生碎特别酥脆。非常有重庆街头的味道，是食堂里难得的良心面食，很满意。','2026/1/10 11:42'),(178317,5,298017,4,1001,4,'孜然味超正，有种吃烧烤的感觉。','2026/1/10 11:43'),(178318,23,298018,49,1007,3,'面的碱味稍微有点重，吃起来不太习惯。汤底感觉调料味太浓，吃完之后口渴得厉害，不太喜欢。','2026/1/10 11:45'),(178319,2,298019,1,1001,5,'这里的肉量对得起价格，算是食堂里比较良心的清真炒菜了，干净卫生。','2026/1/10 11:53'),(178320,3,298020,21,1004,4,'咸香入味层次分明，口感松软不粘牙，打饭快，干净新鲜，挺喜欢','2026/1/10 11:54'),(178321,10,298021,72,1009,4,'豉油鸡味道很香，价格亲民。窗口打饭节奏快，排队时长短，鸡肉肉眼可见干净新鲜，喜欢。','2026/1/10 11:56'),(178322,17,298022,50,1007,4,'豌豆软糯，12元的价格合理，排队时长三分钟，肉沫和豌豆都干净新鲜，喜欢。','2026/1/10 12:00'),(178323,23,298023,72,1009,2,'味道太甜腻了，15元的价格不值。窗口打饭效率低，排队时长久，感觉食材处理得不干净新鲜。','2026/1/10 12:07'),(178324,29,298024,37,1006,4,'牛肉串口味不错，肉质还行，但和羊肉串比还是差一点','2026/1/10 12:11'),(178325,6,298025,21,1004,3,'口感偏硬没发酵好，味道寡淡，窗口拿取快，食材新鲜度一般，不喜欢','2026/1/10 12:16'),(178326,25,298026,72,1009,4,'口感可以，15元的价格适中。排队时长在接受范围内，鸡肉吃着比较干净新鲜。','2026/1/10 12:23'),(178327,22,298027,38,1006,5,'已经点过好多次了，百吃不腻，没吃的都来尝尝!','2026/1/10 12:32'),(178328,7,298028,1,1001,4,'已回购多次，超级美味。','2026/1/10 12:34'),(178329,3,298029,57,1008,2,'酱给太多味道太浓，盖住鸡肉本味，只剩酱。','2026/1/10 12:39'),(178330,30,298030,46,1007,5,'调料配比绝了，里面的宽粉特别Q弹。这种重口味的麻辣拌简直是下饭神器，一周吃三次都觉得好。','2026/1/10 12:43'),(178331,16,298031,1,1001,5,'牛肉分量超良心，黑椒汁拌着河粉特别入味，窗口收拾得也很干净。','2026/1/10 12:43'),(178332,6,298032,58,1008,5,'剁椒豆豉味正，13元够辣，还能免费续饭。','2026/1/10 12:45'),(178333,8,298033,59,1008,5,'辣香十足，肉片肥瘦合适，非常下饭，个人很喜欢。价格合理，排队稍久但出餐快。','2026/1/10 12:46'),(178334,7,298034,43,1007,2,'感觉味道不如以前了，面条煮得太烂，鸡杂给的量也变少了，真心不喜欢现在的口感，以后不打算买了。','2026/1/10 12:52'),(178335,7,298035,39,1006,4,'五花肉肥瘦相间，烤得比较香，但吃多了会有点腻','2026/1/10 12:57'),(178336,28,298036,38,1006,5,'羊肉串真的好吃，3 串 12 元，肉很嫩不膻，中午排队大概 8 分钟，但出串挺快。','2026/1/10 13:00'),(178337,10,298037,4,1001,5,'档口大叔认人很准，出餐效率在炒菜里算高的，排队秩序维持得好。','2026/1/10 13:01'),(178338,22,298038,1,1001,3,'牛肉偶尔会带筋，嚼不太动。排队的人实在太多了，等位比较辛苦。','2026/1/10 13:02'),(178339,8,298039,63,1008,4,'现炒锅气足，排队8分钟，师傅动作麻利。','2026/1/10 13:05'),(178340,28,298040,59,1008,3,'今天特别咸，吃完狂喝水，排队20分钟不值得。','2026/1/10 13:08'),(178341,1,298041,63,1008,5,'免费加辣味道可调，回购很多次，性价比高。','2026/1/10 13:09'),(178342,11,298042,64,1008,5,'花生脆鸡丁嫩，酸甜微辣15元，吃着香。','2026/1/10 13:14'),(178343,16,298043,22,1004,4,'面皮松软有麦香，口感扎实不塌陷，干净新鲜，打饭快，挺喜欢','2026/1/10 13:14'),(178344,22,298044,64,1008,2,'今天葱炒焦了发苦，像锅底刮下来的，品控差。','2026/1/10 13:19'),(178345,11,298045,4,1001,2,'去晚了基本就剩下碎肉和洋葱了，性价比在收尾阶段大幅下降。','2026/1/10 13:26'),(178346,27,298046,72,1009,5,'豉油鸡的皮色泽金黄，肉质滑嫩多汁。汤汁拌饭我能吃两碗，是食堂里百吃不厌的经典款。','2026/1/10 13:28'),(178347,5,298047,72,1009,2,'鸡肉分量缩水严重，只有零星几块。味道也变得大不如前，越来越没有性价比了，很不喜欢。','2026/1/10 13:28'),(178348,28,298048,4,1001,2,'孜然味太重了，吃完一下午嘴里都是那个味道，社交之前不建议点。','2026/1/10 13:29'),(178349,17,298049,23,1004,5,'外皮酥脆内里松软，不油腻，窗口拿取快，新鲜出锅，超喜欢','2026/1/10 17:30'),(178350,12,298050,50,1007,2,'排队时长20分钟让人崩溃，窗口打饭节奏太慢，感觉食材不够干净新鲜，失望。','2026/1/10 17:30'),(178351,30,298051,73,1010,5,'汤头鲜美，牛肉馅很大，能吃出芹菜的清香，很喜欢。窗口打饭速度飞快，食材看着挺新鲜干净的。','2026/1/10 17:34'),(178352,30,298052,50,1007,5,'味道不错，价格也算合适。窗口打饭挺快，排队时长3分钟左右，关键是食材看着干净新鲜，推荐。','2026/1/10 17:40'),(178353,17,298053,5,1001,4,'分量真的大，女生两个人吃一份都够，食材搭配感觉比较有营养。','2026/1/10 17:40'),(178354,2,298054,65,1009,5,'18元的双拼分量足，排队时长极短，肉质吃着干净新鲜，特别喜欢。','2026/1/10 17:40'),(178355,22,298055,73,1010,3,'味道一般，汤有点咸了，牛肉馅偏碎。价格15元略贵，排队等了快十分钟，性价比不是很高，不推荐。','2026/1/10 17:48'),(178356,21,298056,73,1010,3,'饺子皮稍微有点厚了，吃起来口感略硬。不过芹菜肉馅调味很不错，清爽不腻。15元一份性价比一般，不用排队这点挺好。','2026/1/10 17:52'),(178357,1,298057,23,1004,2,'油条发软不酥脆，有油耗味，排队3分钟，食材不新鲜，不太喜欢','2026/1/10 17:56'),(178358,3,298058,2,1001,5,'只要13块钱，鸡蛋和牛肉的双重蛋白质，性价比极高，','2026/1/10 17:56'),(178359,25,298059,50,1007,5,'杂酱和豌豆融合得非常完美，拌开之后香气扑鼻。豌豆绵软入味，是我在食堂吃过的最好吃的豌杂。','2026/1/10 18:09'),(178360,2,298060,5,1001,3,'里面的牛肉片其实挺少的，大部分都是金针菇，感觉在吃素食。','2026/1/10 18:13'),(178361,8,298061,24,1004,4,'饼皮酥脆夹菜丰富，酱料香浓，排队5分钟，干净新鲜，很喜欢','2026/1/10 18:20'),(178362,29,298062,46,1007,3,'感觉食材煮得有点过头了，蔬菜都碎了。味道偏甜不是我喜欢的类型，整体感觉一般，没啥记忆点。','2026/1/10 18:28'),(178363,30,298063,65,1009,2,'烧鸭太肥了，价格贵。排队时长排了很久，感觉肉质不够干净新鲜，不喜欢。','2026/1/10 18:43'),(178364,29,298064,65,1009,4,'味道中规中矩，价格还行。窗口打饭排队时长能忍，双拼的肉看起来干净新鲜。','2026/1/10 18:44'),(178365,13,298065,74,1010,4,'饺子皮薄厚适中，三鲜馅料很足，食材新鲜。虽然排队人多，但阿姨手脚利索，打饭挺快，整体很满意。','2026/1/10 18:52'),(178366,11,298066,74,1010,2,'比较失望，鸡肉馅有点干硬，没感觉到鲜味。而且餐具感觉没洗干净，价格虽便宜但不想再吃第二次了。','2026/1/10 18:58'),(178367,21,298067,65,1009,5,'烧鸭皮脆肉嫩，豉油鸡咸鲜适口。配上特制的蘸酱简直是绝配，分量大到男孩子也能吃得很饱。','2026/1/10 19:14'),(178368,10,298068,59,1008,5,'锅气足肉片嫩青椒脆，分量够吃，窗口看着干净。','2026/1/10 19:14'),(178369,26,298069,47,1007,5,'酸菜很够味，9元价格实在。排队时长很短，肉丝吃得出干净新鲜，非常喜欢。','2026/1/10 19:17'),(178370,19,298070,74,1010,5,'里面的木耳和虾仁都很新鲜，咬下去有汁水。汤底味道也很鲜美，喝得出是用心熬的。阿姨打饭动作快，干净卫生，强推！','2026/1/10 19:17'),(178371,14,298071,75,1010,5,'抄手个头很大，皮滑馅嫩，非常喜欢这个红油口味！窗口不需要排队，价格也公道，是食堂里的宝藏菜品。','2026/1/10 19:23'),(178372,17,298072,75,1010,3,'味道中规中矩，牛肉和芹菜的比例还可以。就是等的时间太长了，前面排了十几个人，打饭速度有待提高。','2026/1/10 19:28'),(178373,14,298073,2,1001,3,'窗口打饭太慢，师傅只有一双手，人多的时候至少要等十分钟以上。','2026/1/11 8:30'),(178374,3,298074,2,1001,3,'整体调味偏淡，建议自己去调料台加点辣椒，不然吃到最后没味道。','2026/1/11 11:56'),(178375,6,298075,2,1001,5,'味道比较家常，河粉软硬适中，档口大叔态度挺好。','2026/1/11 12:17'),(178376,18,298076,2,1001,2,'卫生状况一般，有时候能看到灶台旁边有溢出的油渍。','2026/1/11 13:29'),(178377,29,298077,5,1001,3,'味道稍微有点偏甜，吃多了容易腻。','2026/1/11 7:03'),(178378,25,298078,6,1001,5,'意面Q弹有嚼劲，中式炒法很有创意，15元能吃得非常饱，必试。','2026/1/11 7:31'),(178379,22,298079,6,1001,5,'牛肉片新鲜，鸡蛋炒得很碎且均匀，是食堂里难得的西式精品。','2026/1/11 8:09'),(178380,20,298080,7,1001,4,'窗口效率很高，师傅炒面节奏感很强，面条根根分明，不粘连。','2026/1/11 11:31'),(178381,24,298081,7,1001,3,'有点油腻，吃完碗底剩了一层底油。孜然味虽然香，但也容易腻。','2026/1/11 11:40'),(178382,16,298082,8,1002,5,'豆花滑嫩如布丁，鸡肉分量足，12元套餐还送小菜，出餐秒拿。','2026/1/11 11:44'),(178383,27,298083,8,1002,5,'这里的食材流转快，所以豆花和鸡肉都挺新鲜，适合快速解决战斗。','2026/1/11 12:14'),(178384,26,298084,9,1002,3,'热量太高了，偶尔吃还行，天天吃觉得腻，而且油的味道偏重。','2026/1/11 12:18'),(178385,8,298085,10,1002,4,'肥牛看着挺新鲜，不是那种全是碎渣的。','2026/1/11 12:21'),(178386,13,298086,10,1002,3,'去晚了豆花就凉了，热度不够时口感大打折扣，卫生细节待加强。','2026/1/11 12:45'),(178387,12,298087,10,1002,1,'窗口排队很长，但给的份量全凭阿姨心情，有时候肉少得可怜。','2026/1/11 13:07'),(178388,30,298088,11,1002,5,'只要10块钱！简直是省钱神器，鸡蛋和豆花的组合清爽又管饱。','2026/1/11 17:33'),(178389,23,298089,12,1002,2,'鱼片是冷冻的，吃起来稍微有点水，新鲜度一般。','2026/1/11 17:39'),(178390,14,298090,12,1002,2,'排队的时候经常有人插队，窗口秩序没人维护，用餐体验较差。','2026/1/11 19:03'),(178391,13,298091,25,1004,5,'馅料新鲜蔬菜脆嫩，面皮松软，打饭快，干净卫生，挺喜欢','2026/1/11 7:14'),(178392,29,298092,25,1004,2,'馅料少还偏咸，面皮发硬，窗口拿取快，食材新鲜度一般，不喜欢','2026/1/11 7:30'),(178393,21,298093,26,1004,5,'豆香浓郁口感醇厚，不甜不腻，打饭快，新鲜现磨，超喜欢','2026/1/11 7:53'),(178394,9,298094,26,1004,3,'豆浆兑水太多没豆香，偏甜，窗口拿取快，口感一般，不太喜欢','2026/1/11 12:08'),(178395,22,298095,27,1004,4,'粥体绵密有米油，清淡养胃，窗口打饭快，干净新鲜，很喜欢','2026/1/11 12:33'),(178396,2,298096,28,1005,5,'豌杂拌面 14 元一份，肉酱给得多，味道很香，个人觉得是学校最好吃的面食','2026/1/11 12:36'),(178397,14,298097,28,1005,3,'今天的面有点坨了，豌豆也不够烂，拌不均匀。味道还可以但口感扣分，希望保持水准','2026/1/11 13:11'),(178398,23,298098,29,1005,1,'本陕西人从来没吃过这么难吃的油泼面，面都坨了，根本拌不动，差评','2026/1/11 13:26'),(178399,19,298099,29,1005,2,' 油泼得不够均匀，一半面没味道一半又太辣。14元性价比一般，不会再点','2026/1/11 19:29'),(178400,26,298100,38,1006,5,'每次必点羊肉串，孜然味很香','2026/1/11 11:37'),(178401,22,298101,38,1006,4,'羊肉串火候很好，肉质新鲜，一串 4 元，价格不算便宜但味道对得起。','2026/1/11 12:04'),(178402,15,298102,38,1006,4,'饭点人很多，排队差不多 10 分钟，不过窗口翻台快，基本 2 分钟就出一批。','2026/1/11 12:05'),(178403,18,298103,38,1006,5,'羊肉串很香，外焦里嫩，吃着挺满足，卫生也看着干净。','2026/1/11 12:06'),(178404,9,298104,38,1006,4,'味道稳定，基本不会踩雷，就是中午 12 点左右排队要 10 多分钟。','2026/1/11 12:22'),(178405,3,298105,38,1006,4,'肉挺新鲜，没有异味，出餐速度还行','2026/1/11 18:42'),(178406,17,298106,40,1006,5,'韭菜挺新鲜，调料味道重，配着肉串吃不错，便宜又出得快。','2026/1/11 17:19'),(178407,5,298107,41,1006,4,'蒜香味足，口感软烂，茄子很新鲜','2026/1/11 12:07'),(178408,6,298108,42,1006,3,'烤面包片一份 6 元，量不多，口感偏硬，感觉性价比不高。','2026/1/11 12:52'),(178409,3,298109,42,1006,3,'排队等了快 7 分钟，拿到的面包片有点焦，吃着又干又硬。','2026/1/11 13:15'),(178410,15,298110,42,1006,3,'面包片烤得不均匀，有的地方糊了','2026/1/11 17:31'),(178411,27,298111,42,1006,2,'出餐挺慢的，等了差不多 8 分钟，味道却很普通，不太值。','2026/1/11 18:41'),(178412,23,298112,42,1006,2,'面包感觉不太新鲜，边缘发硬，价格偏高','2026/1/11 18:57'),(178413,9,298113,44,1007,4,'菜品种类多且干净新鲜，价格是称重的比较透明。排队时长较短，窗口打饭很给力，非常喜欢。','2026/1/11 7:56'),(178414,3,298114,44,1007,2,'味道一般，价格稍微贵了点。高峰期排队时长太恐怖，窗口打饭效率极低，体验感不好，不喜欢。','2026/1/11 11:35'),(178415,2,298115,44,1007,4,'口味偏重但很过瘾，食材感觉干净新鲜。虽然价格涨了点，但窗口打饭的排队时长能接受。','2026/1/11 12:21'),(178416,20,298116,44,1007,5,'汤底味道很浓郁，加了麻酱之后特别香。每次来食堂首选就是麻辣烫，怎么吃都吃不腻，超级好评！','2026/1/11 13:08'),(178417,18,298117,44,1007,1,'感觉锅底的油不太好，吃完之后胃不太舒服，味道也偏苦。整体感觉一般，不是特别喜欢，慎重选择。','2026/1/11 18:57'),(178418,23,298118,47,1007,2,'汤底太淡了没味道。价格有点贵，排队时长太久了，窗口打饭太拖拉，感觉食材不是很干净新鲜。','2026/1/11 7:34'),(178419,21,298119,47,1007,4,'味道适中，价格合适，排队时长5分钟左右，在合理范围内，酸菜和肉丝看起来都挺干净新鲜。','2026/1/11 12:12'),(178420,20,298120,47,1007,5,'汤头鲜美，酸菜的酸爽完美去除了肉丝的油腻感。面条分量很足，吃完胃里暖暖的，特别舒服。','2026/1/11 12:42'),(178421,19,298121,47,1007,3,'面的分量有点少，肉丝也没几根，基本全是面汤。性价比不高，口味也一般般，不太推荐这一款。','2026/1/11 18:28'),(178422,17,298122,48,1007,5,'牛肉块很大，价格对得起分量。排队时长短，食材干净新鲜，十分喜欢。','2026/1/11 19:06'),(178423,20,298123,50,1007,2,'口味有点偏咸了，吃多了觉得腻。面的质感一般，没有想象中那么好，总体评分一般，不喜欢。','2026/1/11 7:43'),(178424,14,298124,51,1008,5,'咸香下饭，茄子软烂豆角爽脆，整体挺喜欢。价格实惠，排队5分钟左右，出餐快，食材新鲜。','2026/1/11 8:21'),(178425,11,298125,51,1008,3,'味道稍微偏油，烧肉里肥肉有点多，吃到后面容易腻。价格便宜，但人多的时候要排队，卫生情况一般，属于能吃但不惊艳。','2026/1/11 11:43'),(178426,9,298126,52,1008,4,'葱香味很浓，肉片炒得挺嫩，配米饭吃很下饭，冬天吃着暖和，价格合理，平时几乎不用排队，窗口动作快。','2026/1/11 13:25'),(178427,24,298127,52,1008,4,'味道中规中矩，谈不上惊喜但也不难吃。学生价友好，出餐效率高，适合赶时间随便吃一顿。','2026/1/11 17:35'),(178428,26,298128,53,1008,3,'辣度不太稳定，今天偏辣，鸡丁略干。价格还能接受，下课人多时需要稍微等一下。','2026/1/11 18:38'),(178429,27,298129,53,1008,2,'鸡丁有腥味，腌制时间明显不够，吃完口干。','2026/1/11 19:06'),(178430,23,298130,59,1008,5,'辣椒新鲜，肉量足，口味很香。价格实惠，窗口打饭快，卫生不错。','2026/1/11 7:13'),(178431,10,298131,59,1008,5,'性价比不错，可以免费续饭，辣度刚好适合我的口味','2026/1/11 7:20'),(178432,7,298132,59,1008,4,'油确实比较多，但拌饭特别香，16元价格也算实惠','2026/1/11 11:35'),(178433,19,298133,65,1009,2,'骨头太多肉太少，吃起来很费劲。豉油鸡的皮有点烂烂的，口感不好，整体期望值过高了，一般。','2026/1/11 11:49'),(178434,14,298134,66,1009,5,'味道鲜美，价格实惠。排队时长很短，窗口打饭特别快，食材处理得干净新鲜，满意。','2026/1/11 12:01'),(178435,17,298135,66,1009,2,'卤鸭太咸，18元的价格不值。窗口打饭效率极低，排队时长太久，感觉食材放了很久不干净新鲜。','2026/1/11 12:03'),(178436,14,298136,66,1009,4,'总体味道还可以，价格合理。排队时长适中，肉和配菜都很干净新鲜，好评。','2026/1/11 12:14'),(178437,18,298137,66,1009,5,'豉油鸡的香味渗进了米饭里，卤鸭也很入味。两者的搭配非常有层次感，是食堂港式档口的佳作。','2026/1/11 17:44'),(178438,25,298138,66,1009,3,'鸡肉有点柴，卤鸭的色泽看着不太诱人。整体味道偏平淡，没有那种鲜香的感觉，不会再买了。','2026/1/11 18:18'),(178439,20,298139,67,1009,5,'鸭腿很大只，价格良心。窗口打饭利索，排队时长短，食材肉眼可见的干净新鲜，很喜欢。','2026/1/11 18:27'),(178440,16,298140,67,1009,2,'感觉肉质有点老，价格偏高。排队时长太久，窗口打饭太慢，怀疑食材不是特别干净新鲜。','2026/1/11 18:31'),(178441,17,298141,67,1009,4,'味道还可以，18元的价格中等。窗口打饭排队时长一般，肉类分量足且干净新鲜，还不错。','2026/1/11 19:14'),(178442,13,298142,67,1009,5,'鸭腿肉很厚实，豉油鸡的汁水很丰富。拌在饭里特别香，每次吃完都觉得非常有幸福感，很值。','2026/1/11 19:19'),(178443,30,298143,75,1010,2,'今天的红油有点太辣了，呛得人咳嗽。肉馅感觉不是很紧实，有点散。排队人挺多，等了很久才拿到，体验稍微有点失望。','2026/1/11 11:54'),(178444,30,298144,76,1010,4,'油条酥脆，鸡肉量很大，炒得很有镬气，食材新鲜。18元一份价格偏高，但口味真的很赞，排队也值了。','2026/1/11 12:38'),(178445,29,298145,76,1010,1,'炒得太油腻了，油条都软塌塌的，不喜欢。窗口阿姨态度一般，而且感觉厨房卫生状况堪忧，不会再买了。','2026/1/11 12:42'),(178446,15,298146,76,1010,4,'第一次吃这种搭配，意外地好吃！浸满酱汁的油条软糯入味，鸡肉也超多。虽然要排队二十分钟，但为了这口味道完全值得。','2026/1/11 13:02'),(178447,5,298147,77,1010,5,'酱汁浓郁辛辣，米粉Q弹，正宗的新疆味道！打饭窗口效率高，食材干净卫生，喜欢吃辣的朋友一定要尝试。','2026/1/11 13:13'),(178448,23,298148,77,1010,2,'太辣了受不了，而且米粉感觉没煮透，硬邦邦的。价格偏贵，排队还要半天，食材感觉不怎么新鲜，差评。','2026/1/11 13:14'),(178449,13,298149,77,1010,1,'酱香味很浓，但是真的太油了，吃到底下全是油。米粉有点过于软烂，没有嚼劲。价格在食堂里算贵的，感觉不太划算。','2026/1/11 18:09'),(178450,26,298150,78,1011,5,'汤头非常浓郁，牛肉切得很薄很入味。窗口打饭速度极快，价格便宜，是冬日里最喜欢的暖胃美食。','2026/1/11 18:58'),(178451,15,298151,48,1007,2,'牛肉塞牙不好吃。14元一碗价格小贵，窗口打饭太慢，排队时长等了很久。','2026/1/12 7:00'),(178452,27,298152,78,1011,5,'汤底醇厚浓郁，喝完浑身暖洋洋的。牛肉切得很薄，口感嫩滑。12元的价格在学校里算很实惠了，窗口出餐速度也快，赶时间的首选。','2026/1/12 7:04'),(178453,7,298153,13,1002,5,'肉质紧实不柴，配菜里的咸菜很解腻，分量大到我一个男生都能吃撑。','2026/1/12 7:08'),(178454,21,298154,13,1002,4,'窗口卫生状况良好，烤肉架看着很亮堂，食材更新速度很快。','2026/1/12 7:24'),(178455,21,298155,54,1008,4,'滑蛋做得很嫩，牛肉也比较软，味道偏清淡，不容易腻。18元有点贵。','2026/1/12 7:30'),(178456,1,298156,67,1009,2,'酱汁给得太少了，白米饭没味道。肉的部分骨头占比太大，感觉性价比有点低，不是太喜欢吃。','2026/1/12 7:38'),(178457,26,298157,30,1005,4,'大盘鸡拌面分量挺足，鸡肉新鲜不柴，汤汁拌面很好吃，就是价格略高一点。','2026/1/12 7:51'),(178458,13,298158,45,1007,5,'炸酱味道正宗，价格便宜。窗口打饭排队时长不到5分钟，食材也干净新鲜，很喜欢。','2026/1/12 8:07'),(178459,17,298159,68,1009,5,'鸡肉鲜嫩，价格合适。窗口打饭很快，排队时长不到五分钟，食材感觉非常干净新鲜，喜欢。','2026/1/12 8:10'),(178460,28,298160,30,1005,5,'每周三必吃！性价比之王，比外面餐馆40多的还好吃。就是出锅慢，建议提前手机下单','2026/1/12 8:29'),(178461,10,298161,45,1007,2,'酱料给得太少了，拌不开。排队时长等得心烦，窗口打饭快慢不均，价格和品质不成正比，不喜欢。','2026/1/12 8:33'),(178462,22,298162,30,1005,5,' 新疆同学认证的正宗味道！鸡肉量足，配菜丰富。打饭阿姨每次都多给一勺汤，暖心！','2026/1/12 8:39'),(178463,11,298163,68,1009,2,'味道太淡没灵魂，价格贵。排队时长太久，窗口打饭太拖，感觉鸡肉不怎么干净新鲜。','2026/1/12 8:40'),(178464,16,298164,2,1001,1,'河粉有时候会粘连成一坨，没有完全炒散。','2026/1/12 8:44'),(178465,11,298165,14,1002,5,'米饭可以随便加，简直是饭量大者的福利，味道不输外面品牌店。','2026/1/12 8:46'),(178466,12,298166,68,1009,4,'口味清淡健康，价格公道。窗口打饭稳定，排队时长合理，整体感觉干净新鲜，比较满意。','2026/1/12 8:47'),(178467,10,298167,14,1002,2,'价格太贵了，每次排队还要等很久，不推荐。','2026/1/12 8:47'),(178468,29,298168,15,1003,5,'汤头鲜醇裹着粉条，肉末量足香嫩，窗口打饭快，食材新鲜，口味偏淡挺喜欢','2026/1/12 8:57'),(178469,18,298169,59,1008,4,'香味重，下饭能力强，适合重口。价格正常，出餐速度快，台面干净。','2026/1/12 11:30'),(178470,18,298170,68,1009,5,'姜葱蘸料是这碗饭的灵魂，白切鸡皮爽肉滑。非常适合想吃肉又怕油腻的同学，健康又美味。','2026/1/12 11:32'),(178471,9,298171,38,1006,4,'羊肉串口味偏重但好吃，人少的时候基本不用排队。','2026/1/12 11:34'),(178472,23,298172,54,1008,4,'牛肉给得偏少，性价比一般。价格略高，不过环境相对干净，适合偶尔换口味。','2026/1/12 11:35'),(178473,24,298173,78,1011,2,'感觉今天的汤有点腥，姜味太重了把牛肉鲜味都盖住了。而且排队的人太多，队伍动得很慢，等了快十五分钟才排到，体验一般。','2026/1/12 11:37'),(178474,14,298174,79,1011,3,'牛肚处理得干净，嚼劲十足。但是汤里盐放多了，有点咸。排队时长还可以，就是碗边感觉有点油。','2026/1/12 11:37'),(178475,11,298175,48,1007,5,'味道香辣过瘾，价格中等。排队时长可以接受，窗口打饭快慢挺好的，食材感觉比较干净新鲜。','2026/1/12 11:42'),(178476,12,298176,48,1007,5,'红油色泽诱人，牛肉炖得很软烂入味。面条吸满了汤汁，每一口都很扎实，是高品质的小面。','2026/1/12 11:49'),(178477,15,298177,79,1011,5,'牛肚处理得非常干净，一点异味都没有，软烂中带着嚼劲。配上店里的辣椒油简直绝了！食材看着就很新鲜，分量也给得足，吃得很过瘾。','2026/1/12 11:50'),(178478,7,298178,45,1007,5,'味道还可以，排队时长短，11元的价格亲民，菜码看着干净新鲜。','2026/1/12 11:54'),(178479,2,298179,15,1003,2,'肉末发柴汤味寡淡，排队约8分钟，碗边有油渍，食材新鲜度一般，不太喜欢','2026/1/12 11:56'),(178480,9,298180,16,1003,5,'酸菜酸爽解腻，肉末与酸菜搭配和谐，粉条筋道，打饭麻利，干净新鲜超爱','2026/1/12 11:56'),(178481,22,298181,68,1009,3,'感觉鸡肉没煮透，有的地方还带点血丝。虽然知道白切鸡是这样，但心理上还是觉得不够新鲜。','2026/1/12 11:56'),(178482,13,298182,60,1008,4,'酸甜适中，肉丝细嫩，味道经典。价格实惠，排队不久，出餐快。','2026/1/12 12:00'),(178483,3,298183,45,1007,5,'面条口感爽滑，炸酱肉丁很大块，咸甜适中。对于爱吃拌面的我来说，这碗面简直是午餐的最佳选择。','2026/1/12 12:02'),(178484,16,298184,79,1011,2,'牛肚煮得太老了，根本咬不动，腮帮子都嚼酸了。汤虽然很烫但是特别咸，喝完口特别干，感觉像是味精放多了，不太健康。','2026/1/12 12:03'),(178485,16,298185,31,1005,4,'面比较清淡，口味不刺激，适合不吃辣的人，价格便宜','2026/1/12 12:05'),(178486,15,298186,60,1008,2,'胡萝卜丝太硬，明显没炒熟，像生吃一样。','2026/1/12 12:06'),(178487,15,298187,80,1011,4,'味道很鲜美，能喝出是真材实料熬出来的，食材很新鲜。虽然价格比普通汤贵两块，但物超所值。','2026/1/12 12:09'),(178488,29,298188,16,1003,3,'酸菜过咸掩盖肉香，排队5分钟，粉略坨，食材新鲜度一般，口味不算出众','2026/1/12 12:12'),(178489,26,298189,69,1009,5,'鸭腿卤得很入味，15元的价格实惠。窗口打饭很给力，排队时长短，食材看着干净新鲜，非常喜欢。','2026/1/12 12:13'),(178490,15,298190,80,1011,5,'真的很鲜，能喝出来是老母鸡慢火炖的，上面飘着金黄的鸡油。鸡肉炖得软烂脱骨，食材非常新鲜，虽然比其他汤贵几块钱，但营养价值高，值得。','2026/1/12 12:16'),(178491,17,298191,48,1007,2,'实在是太辣了，根本吃不出牛肉的味道。面条分量一般，对于不吃辣的人来说太不友好了，不喜欢。','2026/1/12 12:18'),(178492,5,298192,17,1003,5,'酱料浓郁鲜香，花生碎酥脆提味，粉条爽滑劲道，打饭快超干净，超喜欢','2026/1/12 12:18'),(178493,22,298193,69,1009,3,'鸭腿太小了，15元的价格偏贵。窗口打饭太慢，排队时长太长，感觉卤味不够干净新鲜，不喜欢。','2026/1/12 12:20'),(178494,19,298194,69,1009,4,'味道尚可，价格中规中矩。排队时长能接受，窗口打饭正常，鸭腿和青菜都挺干净新鲜。','2026/1/12 12:22'),(178495,21,298195,80,1011,1,'稍微有点过于油腻了，喝多了有点反胃，适合喜欢重油的人。而且碗边也不擦干净，拿的时候弄了一手油，卫生细节方面需要加强。','2026/1/12 12:26'),(178496,14,298196,69,1009,5,'卤汁味道极其浓郁，鸭腿轻轻一撕就肉骨分离。配上食堂的大米饭，简直是简单又完美的午餐。','2026/1/12 12:27'),(178497,20,298197,81,1011,5,'牛杂的分量给得很足，清洗得很干净。窗口大叔打饭很热情，速度也快，整体用餐体验非常好。','2026/1/12 12:30'),(178498,7,298198,42,1006,2,'本来是凑单买的，结果味道很一般，不推荐','2026/1/12 12:32'),(178499,18,298199,32,1005,3,'羊肉烩面价格 16 元，汤味还行，但饭点排队差不多要 10 分钟。','2026/1/12 12:35'),(178500,15,298200,33,1005,4,'好吃不贵！','2026/1/12 12:39'),(178501,24,298201,38,1006,5,'孜然香味足，吃着不油腻，算是烧烤区最受欢迎的。','2026/1/12 12:39'),(178502,15,298202,43,1007,4,'鸡杂处理得干净新鲜，排队时长5分钟左右，但窗口打饭速度还行，整体不错。','2026/1/12 12:39'),(178503,24,298203,17,1003,2,'酱料偏咸太油腻，花生碎受潮发软，排队3分钟，碗底有残渣，不太喜欢','2026/1/12 12:40'),(178504,22,298204,34,1006,5,'千页豆腐外脆里软，口味偏甜辣，每次来都点','2026/1/12 12:41'),(178505,5,298205,45,1007,3,'面条太干了，吃起来没啥风味。炸酱感觉有点腻，配菜也不丰富，不太符合我的口味，不太喜欢。','2026/1/12 12:51'),(178506,27,298206,43,1007,2,'味道太咸了，不怎么喜欢。价格偏高，排队时长快20分钟了，窗口打饭时长太看运气。','2026/1/12 12:53'),(178507,10,298207,69,1009,2,'卤得有点太黑了，看着没食欲。味道也太咸，吃完狂喝水，肉质感觉一般般，不会再点第二次。','2026/1/12 12:54'),(178508,1,298208,3,1001,5,'土豆炖得软糯入味，汤汁拌饭是一绝！强推！','2026/1/12 12:57'),(178509,24,298209,55,1008,5,'土豆烂糊牛肉大块，15元能吃饱，味道香。','2026/1/12 12:59'),(178510,18,298210,81,1011,5,'满满一大碗全是干货，萝卜炖得很入味，并没有喧宾夺主。打饭阿姨手不抖，给的肉很多。性价比超高，冬天晚自习前喝这个最舒服。','2026/1/12 13:00'),(178511,12,298211,70,1009,5,'鸭皮很脆，价格给力。窗口打饭迅速，排队时长短，烧鸭肉质吃着很干净新鲜，很推荐。','2026/1/12 13:06'),(178512,15,298212,17,1003,4,'调味均衡不齁咸，萝卜干爽脆，粉条不坨，窗口干净，打饭快，很喜欢','2026/1/12 13:08'),(178513,14,298213,81,1011,2,'里面的肺片有点怪味，感觉食材不是很新鲜。排队秩序很乱，也没人管，窗口打饭速度慢吞吞的，以后应该不会再来吃这个了。','2026/1/12 13:11'),(178514,7,298214,17,1003,2,'粉条煮得太软没嚼劲，酱料量少没味道，食材新鲜但口味差，不喜欢','2026/1/12 13:13'),(178515,3,298215,61,1008,5,'酸甜清爽，鸡蛋蓬松，简单但好吃。价格便宜，几乎不用排队。','2026/1/12 13:16'),(178516,13,298216,70,1009,2,'烧鸭肉太少全是皮和油，价格不值。排队时长太久，怀疑食材干净新鲜度。','2026/1/12 13:18'),(178517,4,298217,17,1003,5,'花生碎和葱花量足，酱料裹粉均匀，排队6分钟，干净新鲜，超爱这款','2026/1/12 13:27'),(178518,10,298218,42,1006,1,'烤得太干了，吃几口就不想吃了，6 元一份有点亏。','2026/1/12 17:17'),(178519,25,298219,17,1003,2,'吃到小石子影响口感，酱料偏甜不合口味，窗口打饭慢，不太满意','2026/1/12 17:36'),(178520,30,298220,35,1006,3,'鸡翅 5 元一个，味道还可以，就是每次下课时间段人也太多了，等的都没食欲了','2026/1/12 17:41'),(178521,18,298221,17,1003,5,'性价比超高，粉条筋道调味刚好，配菜新鲜，打饭麻利，每天都想吃','2026/1/12 17:42'),(178522,10,298222,18,1003,5,'牛肉片大片紧实，酱料香浓不腻，粉条爽滑，窗口干净打饭快，超喜欢','2026/1/12 17:43'),(178523,30,298223,61,1008,5,'番茄味道浓鸡蛋炒得嫩，11元便宜实惠，窗口干净，适合赶时间吃。','2026/1/12 17:48'),(178524,25,298224,55,1008,5,'土豆炖得很烂，牛肉不柴，汤汁拌饭很香，整体挺满足。价格亲民，我常点，排队时间不长。','2026/1/12 17:52'),(178525,28,298225,61,1008,5,'窗口卫生很好，阿姨都戴手套，看着很放心。','2026/1/12 17:54'),(178526,30,298226,56,1008,5,'蘑菇看着比较新鲜，肉片嫩，味道偏清淡，吃着比较舒服。价格合理，基本不用排队。','2026/1/12 17:59'),(178527,30,298227,18,1003,3,'牛肉片少还嚼不动，酱料过咸，排队10分钟，食材新鲜度一般，不值这价','2026/1/12 18:00'),(178528,16,298228,19,1004,5,'粥体绵密顺滑，皮蛋Q弹瘦肉不柴，窗口打饭快，干净新鲜，超喜欢','2026/1/12 18:19'),(178529,14,298229,82,1011,4,'饼皮酥脆，葱香味浓郁，配汤吃一绝。就是稍微油了点，而且放久了变硬。窗口经常没货需要等。','2026/1/12 18:20'),(178530,5,298230,46,1007,4,'味道又酸又辣很地道，价格划算。排队时长刚好，窗口打饭快慢效率高，食材收拾得干净新鲜，喜欢。','2026/1/12 18:24'),(178531,12,298231,3,1001,4,'出餐速度飞快，基本刷卡即取，牛肉炖得很烂。','2026/1/12 18:24'),(178532,20,298232,56,1008,5,'出餐快排队3分钟，窗口干净师傅手速快。','2026/1/12 18:27'),(178533,13,298233,49,1007,4,'调料很香，9元的价格很亲民。排队时长非常短，窗口打饭速度飞快，青菜叶子也干净新鲜，很喜欢吃。','2026/1/12 18:36'),(178534,17,298234,70,1009,4,'味道还行，价格能接受。窗口排队时长在可控范围，烧鸭看起来挺干净新鲜。','2026/1/12 18:39'),(178535,28,298235,70,1009,5,'烧鸭的油脂溢出来包裹着米饭，香气铺鼻。肉质一点也不柴，分量也很有诚意，吃着非常过瘾。','2026/1/12 18:47'),(178536,16,298236,82,1011,5,'刚出锅的时候最好吃，外酥里嫩，层次分明，葱香扑鼻。两块钱一张很划算，也不会太油，配着咸汤吃简直是绝配，每次必点。','2026/1/12 18:48'),(178537,5,298237,56,1008,5,'汤清味鲜分量足，吃完盘底都干净，很满意。','2026/1/12 18:50'),(178538,7,298238,56,1008,4,'调味偏淡，重口味的同学可能觉得没啥味道。价格不高，出餐快。','2026/1/12 18:51'),(178539,15,298239,19,1004,2,'粥太稀像米汤，皮蛋有腥味，排队2分钟，食材新鲜度一般，不太喜欢','2026/1/12 18:58'),(178540,7,298240,62,1008,5,'豆豉香辣米饭粒粒分明，加蛋不加价12元划算。','2026/1/12 19:02'),(178541,23,298241,36,1006,2,'烤得太干了，酱料也不是很入味，份量也少','2026/1/12 19:10'),(178542,27,298242,70,1009,1,'今天的鸭肉有点腥味，不知道是不是没处理好。感觉品质不稳定，这次吃的体验很差，不喜欢。','2026/1/12 19:15'),(178543,9,298243,57,1008,5,'黑椒酱甜辣正好，鸡柳现炸的脆，16元香。','2026/1/12 19:17'),(178544,15,298244,82,1011,1,'运气不好拿到的已经是凉的了，硬得像石头一样，咬一口掉一地渣，完全嚼不动。油放得太多了，吃完满嘴油，非常腻人。','2026/1/12 19:21'),(178545,22,298245,43,1007,4,'鸡杂面口感不错，食材看着干净新鲜。窗口打饭速度适中，排队时长5分钟在接受范围内，价格再便宜点就好了。','2026/1/12 19:25');
