INSERT INTO `shops` VALUES (1001,'本部清真炒菜','本部清真炒菜窗口致力于提供地道的清真风味，以现点现炒为核心特色。严格遵循清真饮食准则，选用优质牛肉与新鲜时蔬，主打快手炒粉及各式盖饭。','https://wmnqyfqcewymzxqqtjru.supabase.co/storage/v1/object/sign/photo/qingzhenchaocai.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNGFiNjNkNi02ZjdjLTQxMDctOGY4ZS01ODI0ODE1NzA1NmMiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwaG90by9xaW5nemhlbmNoYW9jYWkuanBnIiwiaWF0IjoxNzY4OTExNTc1LCJleHAiOjE3NzE1MDM1NzV9.8VPgjPfqR3sD8dcb6VD50ONIp5kaPG3YNxmsUe7yolI',3.68),(1002,'本部烤肉饭','本部烤肉饭致力于为学生提供快速、管饱且口感丰富的便捷餐食。通过创新的“肉类+豆花”组合，在保持极速出餐的同时，实现了口感与营养的平衡。','https://wmnqyfqcewymzxqqtjru.supabase.co/storage/v1/object/sign/photo/kaoroufan.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNGFiNjNkNi02ZjdjLTQxMDctOGY4ZS01ODI0ODE1NzA1NmMiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwaG90by9rYW9yb3VmYW4uanBnIiwiaWF0IjoxNzY4OTEyMzc3LCJleHAiOjE3NzE1MDQzNzd9.Rz0llODoEJ-OvsxaSaLUK8jXUTbB2eNMwX9PvMDkbD8',3.54),(1003,'南昌拌粉','专注江西地道风味，以米粉的韧性与香辣的配料吸引了大批忠实用户，是食堂中辣味偏好者的聚集地。','https://wmnqyfqcewymzxqqtjru.supabase.co/storage/v1/object/sign/photo/nanchang.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNGFiNjNkNi02ZjdjLTQxMDctOGY4ZS01ODI0ODE1NzA1NmMiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwaG90by9uYW5jaGFuZy5qcGciLCJpYXQiOjE3Njg5MTI0MjYsImV4cCI6MTc3MTUwNDQyNn0.iCxf_SPudkqU2-rpGMec-3Bs42dZ_WqSVPvv0jqCyrE',3.69),(1004,'本部早餐','校园清晨的能量起点，提供种类丰富的传统中式早点，主打新鲜现做与快速交付，是学生晨间高频消费的核心场景。','https://wmnqyfqcewymzxqqtjru.supabase.co/storage/v1/object/sign/photo/zaofan.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNGFiNjNkNi02ZjdjLTQxMDctOGY4ZS01ODI0ODE1NzA1NmMiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwaG90by96YW9mYW4uanBnIiwiaWF0IjoxNzY4OTEyNDUzLCJleHAiOjE3NzE1MDQ0NTN9.bnZ6ZFlE3R_WY-uKHBey1W9EavQo9ueQ9TisaDA8X1U',3.71),(1005,'本部特色面食','汇聚南北面食精粹，长期占据销量榜首。每一根面条都经过严格揉压，确保口感Q弹劲道，是面食爱好者的不二之选。','https://wmnqyfqcewymzxqqtjru.supabase.co/storage/v1/object/sign/photo/mian.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNGFiNjNkNi02ZjdjLTQxMDctOGY4ZS01ODI0ODE1NzA1NmMiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwaG90by9taWFuLmpwZyIsImlhdCI6MTc2ODkxMjUwOCwiZXhwIjoxNzcxNTA0NTA4fQ.DLrg60rl70CxmZoyz5tmHfOnFqNLdqwoUlbCVxsfaQs',3.6),(1006,'烧烤','精选优质肉源与当日新鲜时蔬，配合秘制撒料与精准火候，旨在为您提供最地道的“人间烟火气”。','https://wmnqyfqcewymzxqqtjru.supabase.co/storage/v1/object/sign/photo/shaokao.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNGFiNjNkNi02ZjdjLTQxMDctOGY4ZS01ODI0ODE1NzA1NmMiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwaG90by9zaGFva2FvLmpwZyIsImlhdCI6MTc2ODkxMjUzMiwiZXhwIjoxNzcxNTA0NTMyfQ.1LycAGTW4OJVXPapHJNDOImOzE6mqLxQkddbBms2TiQ',3.67),(1007,'小面香锅麻辣烫','校园里的“多面手”窗口。无论是麻辣鲜香的火锅体验，还是自由定制的麻辣烫，这里支持您根据个人画像自主选择辣度与食材，打造专属美味。','https://wmnqyfqcewymzxqqtjru.supabase.co/storage/v1/object/sign/photo/malatang.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNGFiNjNkNi02ZjdjLTQxMDctOGY4ZS01ODI0ODE1NzA1NmMiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwaG90by9tYWxhdGFuZy5qcGciLCJpYXQiOjE3Njg5MTI1NTIsImV4cCI6MTc3MTUwNDU1Mn0.pRwKk5byD6BYLPd7B5n_rwH_ORk84K0LYH-D2FFyXJ4',3.6),(1008,'现炒盖饭','通过精准的火候控制，让米饭与浓郁汤汁完美融合，为您打造具有“家常温度”的高质量盖饭体验。','https://wmnqyfqcewymzxqqtjru.supabase.co/storage/v1/object/sign/photo/gaifan.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNGFiNjNkNi02ZjdjLTQxMDctOGY4ZS01ODI0ODE1NzA1NmMiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwaG90by9nYWlmYW4uanBnIiwiaWF0IjoxNzY4OTEyNTc2LCJleHAiOjE3NzE1MDQ1NzZ9.I_LqDbABRkOhfh_pPYeWS8J0H9uo7074pdaML6cnPok',4.22),(1009,'本部秘制烧腊','传承经典粤式工艺，主打秘制烧鸭与白切鸡。我们注重火候的精准控制，力求皮脆、肉嫩、汁鲜，为您还原正宗的港式烧味体感。','https://wmnqyfqcewymzxqqtjru.supabase.co/storage/v1/object/sign/photo/shaola.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNGFiNjNkNi02ZjdjLTQxMDctOGY4ZS01ODI0ODE1NzA1NmMiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwaG90by9zaGFvbGEuanBnIiwiaWF0IjoxNzY4OTEyNTk1LCJleHAiOjE3NzE1MDQ1OTV9.606QiyIrqMmb696L7oAaIms-yN7XGIVy7cj7psrc5k8',3.6),(1010,'水饺炒米粉','既有皮薄馅大的手工水饺，也有大火煸炒的干香米粉，为多样化的碳水偏好者提供一站式解决方案。','https://wmnqyfqcewymzxqqtjru.supabase.co/storage/v1/object/sign/photo/shuijiao.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNGFiNjNkNi02ZjdjLTQxMDctOGY4ZS01ODI0ODE1NzA1NmMiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwaG90by9zaHVpamlhby5qcGciLCJpYXQiOjE3Njg5MTI2MzIsImV4cCI6MTc3MTUwNDYzMn0.vFrr1o_KXVOwftxwuIt-FOMXVl4kydlnQ-BXy3ht7QQ',3.27),(1011,'牛肉汤','主打清淡、营养与原味。每日熬制醇厚牛骨高汤，不添加过重调料，让您在忙碌的学习之余，享受一份温润胃心的清爽滋补。','https://wmnqyfqcewymzxqqtjru.supabase.co/storage/v1/object/sign/photo/niuroutang.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNGFiNjNkNi02ZjdjLTQxMDctOGY4ZS01ODI0ODE1NzA1NmMiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwaG90by9uaXVyb3V0YW5nLmpwZyIsImlhdCI6MTc2ODkxMjY2MCwiZXhwIjoxNzcxNTA0NjYwfQ.D4Ww0h2e9AFefj9CJKOVavOjxqirzK-6k3OczXFE6TI',3.6);
